<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {scheduleApi,type Semester} from '../schedules'
const props=defineProps<{revision:number}>()
const emit=defineEmits<{student:[login:string];courses:[semester:number];timetable:[semester:number,major:string|null];changed:[]}>()
type Student={id:number;login_id:string;full_name:string;major:string|null}
type Offering={offering_id:number;course_code:string;course_name:string;major:string|null;section:string;professor:string|null;meeting_count:number}
const terms=ref<Semester[]>([]),selected=ref<Semester|null>(null),students=ref<Student[]>([]),offerings=ref<Offering[]>([])
const loading=ref(false),error=ref(''),confirmDelete=ref(false),busy=ref(false)
let request=0
async function load(){const token=++request;loading.value=true;error.value='';try{const data=await scheduleApi('admin/semesters');if(token!==request)return;terms.value=data.semesters;if(selected.value){const id=selected.value.id;if(terms.value.some(t=>t.id===id))await open(id);else selected.value=null}}catch(e){if(token===request)error.value=e instanceof Error?e.message:'Unable to load semesters.'}finally{if(token===request)loading.value=false}}
async function open(id:number){const token=++request;loading.value=true;error.value='';confirmDelete.value=false;try{const data=await scheduleApi('admin/semesters/'+id);if(token!==request)return;selected.value=data.semester;students.value=data.students;offerings.value=data.offerings}catch(e){if(token===request){selected.value=null;error.value=e instanceof Error?e.message:'Unable to load semester.'}}finally{if(token===request)loading.value=false}}
async function remove(){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{await scheduleApi('admin/semesters/'+selected.value.id,'DELETE');selected.value=null;confirmDelete.value=false;emit('changed');await load()}catch(e){error.value=e instanceof Error?e.message:'Unable to delete semester.';confirmDelete.value=false}finally{busy.value=false}}
onMounted(load);watch(()=>props.revision,()=>{if(!busy.value)void load()})
</script>
<template><section class="card semester-details"><div class="detail-heading"><div><p class="eyebrow">SEMESTER DIRECTORY</p><h2>{{selected ? selected.name+' '+selected.academic_year : 'Your semesters'}}</h2></div><button class="secondary" :disabled="loading||busy" @click="load">Refresh</button></div>
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="loading" role="status">Loading semester…</p>
<template v-else-if="selected"><button class="secondary" @click="selected=null;confirmDelete=false">← All semesters</button><p class="muted">Review linked records before removing this semester. Student accounts are never deleted here.</p>
<h3>Assigned students ({{students.length}})</h3><p v-if="!students.length">No students assigned.</p><ul><li v-for="student in students" :key="student.id"><button class="detail-link" @click="emit('student',student.login_id)">{{student.full_name}} · {{student.login_id}}</button><span>{{student.major||'No major'}} · Edit assigned semesters in Students.</span></li></ul>
<div class="detail-heading"><h3>Courses ({{offerings.length}} offerings)</h3><button class="secondary" @click="emit('courses',selected.id)">Manage courses →</button></div><p v-if="!offerings.length">No course offerings linked.</p><ul><li v-for="course in offerings" :key="course.offering_id"><button class="detail-link" @click="emit('courses',selected.id)">{{course.course_code}} · {{course.course_name}}</button><span>{{course.major||'Unassigned major'}} · Section {{course.section}} · {{course.professor||'No professor'}}</span><button class="secondary" @click="emit('timetable',selected.id,course.major)">{{course.meeting_count}} class meetings · Open timetable →</button></li></ul>
<p v-if="students.length||offerings.length" class="muted">Deletion blocked: {{students.length}} student assignments and {{offerings.length}} course offerings. Manage these links first. Course offerings may also have class meetings or enrolments.</p>
<template v-else><p>No student assignments or course offerings. You can delete this empty semester.</p><button v-if="!confirmDelete" class="secondary" @click="confirmDelete=true">Delete empty semester</button><div v-else role="group" aria-label="Confirm semester deletion"><p>Delete {{selected.name}} {{selected.academic_year}}? This cannot be undone.</p><button :disabled="busy" @click="remove">{{busy?'Deleting…':'Confirm delete'}}</button> <button class="secondary" :disabled="busy" @click="confirmDelete=false">Cancel</button></div></template>
</template><template v-else><p class="muted">Choose a semester to see its students and courses.</p><p v-if="!terms.length">No semesters yet. Create one below.</p><ul><li v-for="term in terms" :key="term.id"><button class="detail-link" @click="open(term.id)">{{term.name}} {{term.academic_year}} →</button></li></ul></template></section></template>
<style scoped>
.semester-details{margin-bottom:24px}.detail-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.detail-heading h2,.detail-heading h3{margin:8px 0}ul{list-style:none;padding:0}li{border-bottom:1px solid #dce5df;padding:12px 0;display:flex;align-items:start;flex-direction:column;gap:8px;overflow-wrap:anywhere}.detail-link{background:transparent;color:#286451;padding:8px 0;text-align:left;text-decoration:underline;font-weight:600;min-height:44px}li span{font-size:13px;color:#60736e}.secondary{font-size:14px}
</style>
